import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { login as apiLogin } from '../services/api';
import { useAuth } from '../context/AuthContext';
import toast from 'react-hot-toast';

export default function LoginPage() {
  const [form, setForm] = useState({ email: '', password: '' });
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      const res = await apiLogin(form);
      login(res.data.token, res.data.user);
      toast.success('Bienvenue !');
      navigate('/dashboard');
    } catch (err) {
      toast.error('Erreur login');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex">

      {/* LEFT SIDE */}
      <div className="hidden lg:flex w-1/2 items-center justify-center relative overflow-hidden bg-gradient-to-br from-green-900 via-emerald-900 to-black">

        <div className="absolute w-[500px] h-[500px] bg-green-500/20 rounded-full blur-3xl"></div>

        <div className="relative z-10 backdrop-blur-xl bg-white/10 border border-white/20 rounded-3xl p-10 text-center shadow-lg">

          <div className="w-28 h-28 mx-auto bg-white/20 rounded-3xl flex items-center justify-center text-white text-3xl font-bold">
            OCP
          </div>

          <h1 className="text-3xl font-bold text-white mt-6">
            Gestion du Stock
          </h1>

          <p className="text-green-100 mt-3 text-sm">
            Plateforme intelligente pour gérer vos équipements
          </p>

        </div>
      </div>

      {/* RIGHT SIDE */}
      <div className="flex w-full lg:w-1/2 items-center justify-center bg-white">

        <form 
          onSubmit={handleSubmit}
          className="w-full max-w-md p-8 space-y-6"
        >

          <div>
            <h2 className="text-2xl font-bold text-gray-800">Bienvenue 👋</h2>
            <p className="text-gray-500 text-sm">Connectez-vous</p>
          </div>

          <input 
            type="email"
            placeholder="Email"
            value={form.email}
            onChange={(e)=>setForm({...form, email:e.target.value})}
            className="w-full px-4 py-3 border rounded-xl"
          />

          <input 
            type="password"
            placeholder="Mot de passe"
            value={form.password}
            onChange={(e)=>setForm({...form, password:e.target.value})}
            className="w-full px-4 py-3 border rounded-xl"
          />

          <button 
            type="submit"
            className="w-full py-3 bg-green-600 text-white rounded-xl"
          >
            {loading ? '...' : 'Se connecter'}
          </button>

        </form>

      </div>

    </div>
  );
}
